// ── Article name lookup (for "Leer más" button) ──
function buildArticleNames() {
  const names = {};
  try {
    const WIKI_DATA = window.WIKI_DATA;
    if (typeof WIKI_DATA !== 'undefined' && WIKI_DATA.articles) {
      WIKI_DATA.articles.forEach(a => { names[a.id] = a.title; });
    }
  } catch(e) {}
  const fallback = {
    'osint':'OSINT - Open Source Intelligence', 'shodan':'Shodan - Buscador de IoT', 'maltego':'Maltego - OSINT',
    'nmap':'Nmap - Escáner de Redes', 'wireshark':'Wireshark - Análisis de Tráfico', 'metasploit':'Metasploit Framework',
    'burp-suite':'Burp Suite - Proxy Web', 'sql-injection':'SQL Injection', 'xss':'Cross-Site Scripting (XSS)',
    'csrf':'CSRF - Cross-Site Request Forgery', 'ssrf':'SSRF - Server Side Request Forgery',
    'jwt':'JWT - JSON Web Tokens', 'owasp-top10':'OWASP Top 10 2021',
    'ransomware':'Ransomware', 'gdpr':'GDPR - Reglamento General de Protección de Datos',
    'mitre-attack':'MITRE ATT&CK Framework', 'linux-comandos':'Comandos Esenciales de Linux',
    'certificados-digitales':'Certificados Digitales', 'tls-ssl':'TLS/SSL - Protocolos de Seguridad',
    'cors':'CORS - Cross-Origin Resource Sharing', 'hsts':'HSTS - Strict Transport Security',
    'csp':'Content Security Policy (CSP)', 'docker':'Docker Security', 'kubernetes':'Kubernetes Security',
    'owasp-top10-llm':'OWASP Top 10 para LLMs',
  };
  Object.keys(fallback).forEach(k => { if(!names[k]) names[k] = fallback[k]; });
  return new Proxy(names, {
    get(t, prop) {
      if (typeof prop === 'string' && !(prop in t)) {
        t[prop] = prop.split('-').map(w => w.charAt(0).toUpperCase() + w.slice(1)).join(' ');
      }
      return t[prop];
    },
  });
}

// ── Convert compact array format to objects ──
function expandQuestions(arr) {
  return arr.map(q => {
    if(q[0]==='multi') return { t:'multi', q:q[1], o:q[2], c:q[3], x:q[4], e:q[5], a:q[6], d:q[7] };
    if(q[0]==='tf')     return { t:'tf', q:q[1], c:q[2], x:q[3], e:q[4], a:q[5], d:q[6] };
    if(q[0]==='fill')   return { t:'fill', q:q[1], b:q[2], o:q[3], c:q[4], x:q[5], e:q[6], a:q[7], d:q[8] };
    if(q[0]==='match')  return { t:'match', q:q[1], p:q[2], x:q[3], e:q[4], a:q[5], d:q[6] };
    if(q[0]==='order')  return { t:'order', q:q[1], steps:q[2], x:q[3], e:q[4], a:q[5], d:q[6] };
    return q;
  });
}

// ── Build and export the QuizData object ──
export const QUIZ_DATA = {
  paths: PATHS,
  questions: {
    osint: [...expandQuestions(Q_OSINT), ...expandQuestions(Q_OSINT_EXT)],
    web: [...expandQuestions(Q_WEB), ...expandQuestions(Q_WEB_EXT)],
    malware: [...expandQuestions(Q_MALWARE), ...expandQuestions(Q_MALWARE_EXT)],
    crypto: [...expandQuestions(Q_CRYPTO), ...expandQuestions(Q_CRYPTO_EXT)],
    pentest: [...expandQuestions(Q_PENTEST), ...expandQuestions(Q_PENTEST_EXT)],
    legal: [...expandQuestions(Q_LEGAL), ...expandQuestions(Q_LEGAL_EXT)],
  },
  articleNames: buildArticleNames(),
};
